class Solution {
  public int evenSumSubgraphs(int[] nums, int[][] edges) {
    int n = nums.length;
    int[] adj = new int[n];
    for (int[] e : edges) {
      adj[e[0]] |= 1 << e[1];
      adj[e[1]] |= 1 << e[0];
    }
    int count = 0;
    for (int mask = 1; mask < (1 << n); mask++) {
      int sum = 0;
      for (int i = 0; i < n; i++) if ((mask >> i & 1) != 0) sum += nums[i];
      if (sum % 2 != 0) continue;
      int seen = mask & -mask, frontier = seen;
      while (frontier != 0) {
        int u = Integer.numberOfTrailingZeros(frontier);
        frontier &= frontier - 1;
        int next = adj[u] & mask & ~seen;
        seen |= next;
        frontier |= next;
      }
      if (seen == mask) count++;
    }
    return count;
  }
}
